function UIActivityRoleLettersDialog:Awake()
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    local id = checkNumber(argument.id)
    self._vo = CfUtils.GetCfVo(AutoIds.IdSetting2831, "SendWordWordVo", id)
    if not self._vo then
        return
    end

    self:FillSelf()
end

function UIActivityRoleLettersDialog:FillSelf()
    CfUtils.FillImage(self.ImgRole, self._vo.picture)
    local roleVo = CardConfMgr:GetInstance():GetRolesByCharacterType(self._vo.characterId)
    CfUtils.FillText(self.TxtName, roleVo.englishName)
    CfUtils.FillText(self.TxtTitle, self._vo.taskTitle)

    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    --女
    if checkInt(playerComp.playerDojo.gender) == Constants.PLAYER_GENDER.FEMALE then
        CfUtils.FillText(self.TxtContent, string.gsub(self._vo.fedesc, "\\n", "\n"))
    else
        CfUtils.FillText(self.TxtContent, string.gsub(self._vo.desc, "\\n", "\n"))
    end
end

